EPOCH = 1767225600000   # 2026-01-01T00:00:00Z
def next_id():
    with lock:
        if not lease.valid(): raise LeaseLost
        now = wall_ms() - EPOCH
        if now < last_ms:
            if last_ms - now <= 5: now = wait_until(last_ms)
            else: raise ClockMovedBackwards(last_ms - now)
        if now == last_ms:
            seq = (seq + 1) & 0xFFF
            if seq == 0: now = wait_until(last_ms + 1)
        else:
            seq = 0
        last_ms = now
        return (now << 22) | (dc << 17) | (worker << 12) | seq

def acquire(dc):
